// server/routes/todoRoutes.js
import { Router } from 'express';
import { body, param, query } from 'express-validator';
import * as controller from '../controllers/todoController.js';
import { validate } from '../middleware/validate.js';

const router = Router();
const idRules = [param('id').isMongoId().withMessage('Invalid todo id')];
const todoRules = [
  body('title').trim().notEmpty().withMessage('Title is required').isLength({ max: 200 }).withMessage('Title must be 200 characters or fewer'),
  body('description').optional({ values: 'falsy' }).isLength({ max: 1000 }).withMessage('Description must be 1000 characters or fewer'),
  body('completed').optional().isBoolean().withMessage('Completed must be true or false'),
  body('priority').optional().isIn(['low', 'medium', 'high']).withMessage('Priority must be low, medium, or high'),
  body('dueDate').optional({ values: 'null' }).isISO8601().withMessage('Due date must be a valid date')
];

router.get('/', [query('completed').optional().isBoolean(), query('priority').optional().isIn(['low', 'medium', 'high'])], validate, controller.getTodos);
router.delete('/completed', controller.deleteCompletedTodos);
router.get('/:id', idRules, validate, controller.getTodo);
router.post('/', todoRules, validate, controller.createTodo);
router.put('/:id', [...idRules, ...todoRules], validate, controller.updateTodo);
router.patch('/:id/toggle', idRules, validate, controller.toggleTodo);
router.delete('/:id', idRules, validate, controller.deleteTodo);

export default router;
